-- Executive KPI Dashboard Phase 4: PSM governance health scoring (not legal certification).
create table if not exists public.executive_psm_elements (id text primary key, company_id text null references public."Tenant"(id) on delete cascade, element_code text not null, element_name text not null, element_description text null, element_category text not null, display_order integer not null default 0, system_defined boolean not null default false, active boolean not null default true, required_foundation boolean not null default false, notes text null, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz null, archived_by text null, archive_reason text null);
create unique index if not exists executive_psm_element_code_unique on public.executive_psm_elements(coalesce(company_id, '__system__'), element_code);
create table if not exists public.executive_psm_element_module_mappings (id text primary key, company_id text null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete cascade, element_id text not null references public.executive_psm_elements(id) on delete cascade, source_module text not null, source_module_label text not null, mapping_type text not null, weight numeric null, required_for_score boolean not null default false, required_permission text null, active boolean not null default true, notes text null, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz null, archived_by text null, archive_reason text null);
create table if not exists public.executive_psm_element_kpi_mappings (id text primary key, company_id text null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete cascade, element_id text not null references public.executive_psm_elements(id) on delete cascade, kpi_definition_id text null, kpi_code text not null, source_module text null, contribution_type text not null, weight numeric null, penalty_config_json jsonb null, required_for_score boolean not null default false, active boolean not null default true, created_by text null, updated_by text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz null, archived_by text null, archive_reason text null);
create table if not exists public.executive_psm_element_scores (id text primary key, company_id text not null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete set null, department_id text null, unit_id text null, area_id text null, equipment_id text null, element_id text not null references public.executive_psm_elements(id) on delete cascade, element_code text not null, aggregation_run_id text null references public.executive_kpi_aggregation_runs(id) on delete set null, scope_type text not null, scope_record_id text null, score_value numeric null check (score_value is null or (score_value >= 0 and score_value <= 100)), element_status text not null, threshold_status text null, confidence_status text null, data_quality_status text not null, critical_item_count integer not null default 0, high_risk_item_count integer not null default 0, overdue_action_count integer not null default 0, missing_evidence_count integer not null default 0, pending_approval_count integer not null default 0, stale_record_count integer not null default 0, restricted_record_count integer not null default 0, excluded_record_count integer not null default 0, source_module_count integer not null default 0, unavailable_module_count integer not null default 0, insufficient_data_count integer not null default 0, score_factor_summary_json jsonb null, calculation_method_snapshot_json jsonb null, source_trace_json jsonb null, calculated_by text null, calculated_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.executive_psm_element_score_factors (id text primary key, company_id text not null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete set null, element_score_id text not null references public.executive_psm_element_scores(id) on delete cascade, factor_key text not null, factor_title text not null, factor_value numeric null, factor_text_value text null, factor_status text not null, factor_weight numeric null, factor_contribution numeric null, source_module text null, source_count integer not null default 0, restricted_count integer not null default 0, explanation_json jsonb null, created_at timestamptz not null default now());
create table if not exists public.executive_psm_element_source_records (id text primary key, company_id text not null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete set null, unit_id text null, element_score_id text null references public.executive_psm_element_scores(id) on delete cascade, element_id text not null references public.executive_psm_elements(id) on delete cascade, source_module text not null, source_record_type text not null, source_record_id text null, source_title text null, contribution_type text null, included boolean not null default true, excluded_reason text null, restricted boolean not null default false, severity text null, status text null, drilldown_route text null, source_snapshot_json jsonb null, created_at timestamptz not null default now());
create table if not exists public.executive_psm_element_gaps (id text primary key, company_id text not null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete set null, unit_id text null, area_id text null, equipment_id text null, element_id text not null references public.executive_psm_elements(id) on delete cascade, element_score_id text null references public.executive_psm_element_scores(id) on delete set null, gap_title text not null, gap_type text not null, source_module text not null, source_record_type text not null, source_record_id text null, severity text not null, criticality text null, gap_status text not null, owner_user_id text null, due_date timestamptz null, age_days integer null, drilldown_route text null, restricted boolean not null default false, source_snapshot_json jsonb null, created_at timestamptz not null default now(), resolved_at timestamptz null, resolved_by text null, resolution_note text null);
create table if not exists public.executive_psm_element_snapshots (id text primary key, company_id text not null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete set null, department_id text null, unit_id text null, area_id text null, equipment_id text null, snapshot_code text null, snapshot_title text not null, snapshot_type text not null, scope_type text not null, scope_record_id text null, aggregation_run_id text null references public.executive_kpi_aggregation_runs(id) on delete set null, element_count integer not null default 0, healthy_count integer not null default 0, monitor_count integer not null default 0, attention_required_count integer not null default 0, high_risk_count integer not null default 0, critical_count integer not null default 0, incomplete_count integer not null default 0, restricted_count integer not null default 0, score_summary_json jsonb null, gap_summary_json jsonb null, action_summary_json jsonb null, evidence_summary_json jsonb null, approval_summary_json jsonb null, calculation_method_snapshot_json jsonb null, source_trace_summary_json jsonb null, generated_by text null, generated_at timestamptz not null default now(), stale_status text null, stale_reason text null, created_at timestamptz not null default now(), archived_at timestamptz null, archived_by text null, archive_reason text null);
create table if not exists public.executive_psm_element_history_events (id text primary key, company_id text not null references public."Tenant"(id) on delete cascade, site_id text null references public."Site"(id) on delete set null, department_id text null, unit_id text null, area_id text null, equipment_id text null, element_id text null, element_score_id text null, snapshot_id text null, mapping_id text null, event_type text not null, event_title text not null, event_description text null, before_value_json jsonb null, after_value_json jsonb null, actor_user_id text null, source_module text not null, source_record_id text null, created_at timestamptz not null default now());
alter table public.executive_kpi_settings add column if not exists enable_psm_element_scoring boolean not null default true, add column if not exists enable_psm_element_heatmap boolean not null default true, add column if not exists enable_psm_element_snapshots boolean not null default true, add column if not exists minimum_modules_for_element_score integer not null default 1, add column if not exists hide_restricted_element_scores boolean not null default false, add column if not exists show_restricted_element_placeholder boolean not null default true, add column if not exists allow_company_custom_psm_elements boolean not null default true, add column if not exists auto_recalculate_elements_after_aggregation boolean not null default true, add column if not exists psm_element_score_method text not null default 'weighted_kpi_and_gap_penalty', add column if not exists psm_element_snapshot_enabled boolean not null default true, add column if not exists psm_element_critical_gap_penalty numeric not null default 15, add column if not exists psm_element_overdue_action_penalty numeric not null default 10, add column if not exists psm_element_missing_evidence_penalty numeric not null default 8, add column if not exists psm_element_stale_record_penalty numeric not null default 6, add column if not exists psm_element_pending_approval_penalty numeric not null default 5;
create index if not exists executive_psm_elements_active_idx on public.executive_psm_elements(company_id, active); create index if not exists executive_psm_element_module_mapping_idx on public.executive_psm_element_module_mappings(element_id, source_module); create index if not exists executive_psm_element_kpi_mapping_idx on public.executive_psm_element_kpi_mappings(element_id, kpi_code); create index if not exists executive_psm_scores_scope_idx on public.executive_psm_element_scores(company_id, site_id, element_code); create index if not exists executive_psm_scores_status_idx on public.executive_psm_element_scores(company_id, site_id, element_status); create index if not exists executive_psm_score_factor_idx on public.executive_psm_element_score_factors(element_score_id, factor_key); create index if not exists executive_psm_source_idx on public.executive_psm_element_source_records(element_id, source_module, source_record_id); create index if not exists executive_psm_gap_idx on public.executive_psm_element_gaps(company_id, site_id, severity); create index if not exists executive_psm_snapshot_idx on public.executive_psm_element_snapshots(company_id, site_id, generated_at); create index if not exists executive_psm_history_idx on public.executive_psm_element_history_events(element_id, created_at);
