do $$
declare
  permission_key text;
begin
  foreach permission_key in array array[
    'executive.psm_element.view', 'executive.psm_element.dashboard.view',
    'executive.psm_element.register.view', 'executive.psm_element.detail.view',
    'executive.psm_element.create', 'executive.psm_element.edit',
    'executive.psm_element.archive', 'executive.psm_element.score.view',
    'executive.psm_element.score.recalculate', 'executive.psm_element.mapping.view',
    'executive.psm_element.mapping.edit', 'executive.psm_element.kpi_mapping.view',
    'executive.psm_element.kpi_mapping.edit', 'executive.psm_element.heatmap.view',
    'executive.psm_element.site_breakdown.view', 'executive.psm_element.unit_breakdown.view',
    'executive.psm_element.gap.view', 'executive.psm_element.source_trace.view',
    'executive.psm_element.restricted_trace.view', 'executive.psm_element.snapshot.view',
    'executive.psm_element.snapshot.create', 'executive.psm_element.snapshot.archive',
    'executive.psm_element.settings.edit'
  ] loop
    insert into public."Permission" ("id", "tenantId", "key", "moduleKey", "label")
    select gen_random_uuid()::text, tenant."id", permission_key, 'EXECUTIVE', permission_key
    from public."Tenant" tenant
    where not exists (
      select 1 from public."Permission" permission
      where permission."tenantId" = tenant."id"
        and permission."key" = permission_key
    );
  end loop;
end $$;
alter table public.executive_psm_elements enable row level security; alter table public.executive_psm_element_module_mappings enable row level security; alter table public.executive_psm_element_kpi_mappings enable row level security; alter table public.executive_psm_element_scores enable row level security; alter table public.executive_psm_element_score_factors enable row level security; alter table public.executive_psm_element_source_records enable row level security; alter table public.executive_psm_element_gaps enable row level security; alter table public.executive_psm_element_snapshots enable row level security; alter table public.executive_psm_element_history_events enable row level security;
